package edu.bigdata.clickstream.dailyfunnel;

import edu.bigdata.clickstream.common.QualityCounter;
import edu.bigdata.clickstream.common.TimeUtil;
import edu.bigdata.clickstream.writable.DailyFunnelWritable;
import org.apache.hadoop.io.LongWritable;
import org.apache.hadoop.io.Text;
import org.apache.hadoop.mapreduce.Counter;
import org.apache.hadoop.mapreduce.Mapper;

import java.io.IOException;

/**
 * DailyFunnelMapper reads partial date-level funnel outputs generated by Job J5
 * and maps them to canonical date keys per SRS §3.3.9 (FR-MR-15).
 *
 * Input:
 *   date \t sessions \t cart \t purchase \t abandoned \t removes
 *
 * Output:
 *   Key:   Text(date)
 *   Value: DailyFunnelWritable(sessions, cart, purchase, abandoned, removes)
 */
public class DailyFunnelMapper extends Mapper<LongWritable, Text, Text, DailyFunnelWritable> {

    private final Text outKey = new Text();
    private final DailyFunnelWritable outVal = new DailyFunnelWritable();

    private void increment(Context context, QualityCounter counter) {
        if (context != null) {
            Counter c = context.getCounter(QualityCounter.GROUP_NAME, counter.name());
            if (c != null) {
                c.increment(1);
            }
        }
    }

    @Override
    protected void map(LongWritable key, Text value, Context context) throws IOException, InterruptedException {
        String line = value.toString().trim();
        if (line.isEmpty()) {
            return;
        }

        increment(context, QualityCounter.TOTAL_RECORDS);

        String[] cols = line.split("\t", -1);
        if (cols.length != 6) {
            increment(context, QualityCounter.MALFORMED_COLUMN_COUNT);
            return;
        }

        String dateStr = cols[0].trim();
        if (!TimeUtil.isValidDate(dateStr)) {
            increment(context, QualityCounter.MALFORMED_TIMESTAMP);
            return;
        }

        long sessions;
        long cart;
        long purchase;
        long abandoned;
        long removes;

        try {
            sessions = Long.parseLong(cols[1].trim());
            cart = Long.parseLong(cols[2].trim());
            purchase = Long.parseLong(cols[3].trim());
            abandoned = Long.parseLong(cols[4].trim());
            removes = Long.parseLong(cols[5].trim());

            if (sessions < 0 || cart < 0 || purchase < 0 || abandoned < 0 || removes < 0) {
                increment(context, QualityCounter.MALFORMED_ID);
                return;
            }
        } catch (NumberFormatException e) {
            increment(context, QualityCounter.MALFORMED_ID);
            return;
        }

        increment(context, QualityCounter.VALID_RECORDS);

        outKey.set(dateStr);
        outVal.set(sessions, cart, purchase, abandoned, removes);
        context.write(outKey, outVal);
    }
}
